          <p>Loading...</p>
        ) : (
          <div>
            <p>
              <strong>Last scan:</strong>{" "}
              {status?.lastScanAt
                ? new Date(status.lastScanAt).toLocaleString()
                : "Never"}
            </p>
            <p>
              <strong>Scan running:</strong>{" "}
              {status?.scanRunning ? "Yes" : "No"}
            </p>
            <button onClick={refresh}>Refresh</button>
          </div>
        )}
      </section>
      <section style={{ marginTop: "1rem" }}>
        <h3>Configuration</h3>
        <p>
