454→- [ ] **Step 1: Create worker.ts**
455→
456→```typescript
457→import { definePlugin, runWorker } from "@paperclipai/plugin-sdk";
458→import type { PluginJobContext } from "@paperclipai/plugin-sdk";
459→import {
460→  fetchTopCoins,
461→  fetchTrendingCoins,
462→  fetchWatchlistCoins,
463→} from "./coingecko.js";
464→import type {
465→  CoingeckoConfig,
466→  CoinData,
467→  ScanResult,
468→  ScanCompletePayload,
469→  PriceAlertPayload,
470→} from "./types.js";
471→
472→const PLUGIN_NAME = "coingecko-scanner";
473→
474→const plugin = definePlugin({
475→  async setup(ctx) {
476→    ctx.logger.info(`${PLUGIN_NAME} plugin setup complete`);
477→
478→    ctx.jobs.register(
479→      "scan-coingecko",
480→      async (_job: PluginJobContext) => {
481→        // Guard: prevent concurrent scans
482→        const scanRunning = await ctx.state.get({
483→          scopeKind: "instance",
484→          stateKey: "scanRunning",
485→        });
486→        if (scanRunning) {
487→          ctx.logger.info("Scan already running, skipping this cycle");
488→          return;
489→        }
490→
491→        try {
492→          await ctx.state.set(
493→            { scopeKind: "instance", stateKey: "scanRunning" },
494→            true,
495→          );
496→
497→          const config =
498→            (await ctx.config.get()) as unknown as CoingeckoConfig;
499→          if (!config?.companyId) {
500→            ctx.logger.warn("companyId not configured, skipping scan");
501→            return;
502→          }
503→
504→          const scanMode = config.scanMode ?? "top";
505→          const currency = config.currency ?? "usd";
506→          const topLimit = config.topCoinsLimit ?? 20;
507→          const watchlistIds = (config.watchlistCoinIds ?? "bitcoin,ethereum,solana")
508→            .split(",")
509→            .map((s) => s.trim())
510→            .filter(Boolean);
511→
512→          // 1. Fetch coins based on scanMode
513→          let coins: CoinData[] = [];
514→          try {
515→            if (scanMode === "top" || scanMode === "all") {
516→              const topCoins = await fetchTopCoins(
517→                ctx.http.fetch.bind(ctx.http),
518→                currency,
519→                topLimit,
520→              );
521→              coins.push(...topCoins);
522→            }
523→            if (scanMode === "trending" || scanMode === "all") {
524→              const trendingCoins = await fetchTrendingCoins(
525→                ctx.http.fetch.bind(ctx.http),
526→              );
527→              coins.push(...trendingCoins);
528→            }
529→            if (scanMode === "watchlist" || scanMode === "all") {
530→              const watchlistCoins = await fetchWatchlistCoins(
531→                ctx.http.fetch.bind(ctx.http),
532→                watchlistIds,
533→                currency,
534→              );
535→              coins.push(...watchlistCoins);
536→            }
537→          } catch (err: unknown) {
538→            const message =
539→              err instanceof Error ? err.message : String(err);
540→            if (message.includes("429")) {
541→              ctx.logger.warn(
542→                `CoinGecko rate limited, skipping this cycle`,
543→              );
544→              return;
545→            }
546→            throw err;
547→          }
548→
549→          // Deduplicate by coin id (keep first occurrence)
550→          const seen = new Set<string>();
551→          coins = coins.filter((c) => {
552→            if (seen.has(c.id)) return false;
553→            seen.add(c.id);
554→            return true;
555→          });
556→
557→          ctx.logger.info(
558→            `Fetched ${coins.length} unique coins (mode: ${scanMode})`,
559→          );
560→
561→          // 2. Load previous scan for comparison
562→          const prevScan = (await ctx.state.get({
563→            scopeKind: "instance",
564→            stateKey: "last-scan",
565→          })) as ScanResult | null;
566→
567→          const prevMap = new Map<string, CoinData>();
568→          if (prevScan?.coins) {
569→            for (const c of prevScan.coins) {
570→              prevMap.set(c.id, c);
571→            }
572→          }
573→
574→          // 3. Compare and detect alerts
575→          const priceThreshold = config.priceChangeThreshold ?? 10;
576→          const volumeThreshold = config.volumeChangeThreshold ?? 50;
577→          let alertsTriggered = 0;
578→
579→          for (const coin of coins) {
580→            const prev = prevMap.get(coin.id);
581→            const priceChange = Math.abs(coin.priceChange24hPercent);
582→
583→            let volumeChange: number | null = null;
584→            if (prev && prev.volume24h > 0) {
585→              volumeChange =
586→                ((coin.volume24h - prev.volume24h) / prev.volume24h) *
587→                100;
588→            }
589→
590→            const priceAlert = priceChange >= priceThreshold;
591→            const volumeAlert =
592→              volumeChange !== null &&
593→              Math.abs(volumeChange) >= volumeThreshold;
594→
595→            if ((priceAlert || volumeAlert) && prevScan !== null) {
596→              alertsTriggered++;
597→              const reasons: string[] = [];
598→              if (priceAlert) {
599→                reasons.push(
600→                  `price ${coin.priceChange24hPercent > 0 ? "+" : ""}${coin.priceChange24hPercent.toFixed(1)}% (24h)`,
601→                );
602→              }
603→              if (volumeAlert) {
604→                reasons.push(
605→                  `volume ${volumeChange! > 0 ? "+" : ""}${volumeChange!.toFixed(1)}%`,
606→                );
607→              }
608→              const reason = reasons.join(", ");
609→
610→              // Emit alert event
611→              const alertPayload: PriceAlertPayload = {
612→                coin,
613→                priceChangePercent: coin.priceChange24hPercent,
614→                volumeChangePercent: volumeChange,
615→                reason,
616→              };
617→              await ctx.events.emit(
618→                "coingecko-price-alert",
619→                config.companyId,
620→                alertPayload,
621→              );
622→
623→              // Create issue
624→              const priority =
625→                priceChange >= 20 ? "high" : "medium";
626→              const sign =
627→                coin.priceChange24hPercent >= 0 ? "+" : "";
628→              await ctx.issues.create({
629→                companyId: config.companyId,
630→                title: `🔔 ${coin.symbol.toUpperCase()} ${sign}${coin.priceChange24hPercent.toFixed(1)}% trong 24h`,
631→                description: `**${coin.name}** (${coin.symbol.toUpperCase()})\n\n- Giá: $${coin.currentPrice.toLocaleString()}\n- Thay đổi 24h: ${sign}${coin.priceChange24hPercent.toFixed(1)}%\n- Volume 24h: $${coin.volume24h.toLocaleString()}\n${volumeChange !== null ? `- Volume change: ${volumeChange > 0 ? "+" : ""}${volumeChange.toFixed(1)}%\n` : ""}\n**Reason:** ${reason}`,
632→                priority,
633→              });
634→
635→              ctx.logger.info(
636→                `Alert: ${coin.symbol} — ${reason}`,
637→              );
638→            }
639→          }
640→
641→          // 4. Save new scan result
642→          const scanResult: ScanResult = {
643→            scannedAt: new Date().toISOString(),
644→            scanMode,
645→            coins,
646→            alertsTriggered,
647→          };
648→          await ctx.state.set(
649→            { scopeKind: "instance", stateKey: "last-scan" },
650→            scanResult,
651→          );
652→
653→          // 5. Emit scan-complete event (always)
654→          const completePayload: ScanCompletePayload = {
655→            scannedAt: scanResult.scannedAt,
656→            coinCount: coins.length,
657→            coins,
658→          };
659→          await ctx.events.emit(
660→            "coingecko-scan-complete",
661→            config.companyId,
662→            completePayload,
663→          );
664→
665→          // 6. Activity log
666→          await ctx.activity.log({
667→            companyId: config.companyId,
668→            message: `Scanned CoinGecko: ${coins.length} coins, ${alertsTriggered} alerts triggered`,
669→            metadata: {
