690→          scopeKind: "instance",
691→          stateKey: "last-scan",
692→        })) as ScanResult | null;
693→        const scanRunning = await ctx.state.get({
694→          scopeKind: "instance",
695→          stateKey: "scanRunning",
696→        });
697→        return {
698→          lastScanAt: lastScan?.scannedAt ?? null,
699→          scanRunning: !!scanRunning,
700→          coinCount: lastScan?.coins.length ?? 0,
701→          alertsTriggered: lastScan?.alertsTriggered ?? 0,
702→        };
703→      },
704→    );
705→  },
706→
707→  async onHealth() {
708→    return { status: "ok", message: "CoinGecko Scanner plugin ready" };
709→  },
710→
711→  async onValidateConfig(config: Record<string, unknown>) {
712→    const errors: string[] = [];
713→    if (!config.companyId) errors.push("companyId is required");
714→    return { ok: errors.length === 0, errors };
715→  },
716→});
