  1→import { definePlugin, runWorker } from "@paperclipai/plugin-sdk";
  2→import type { PluginJobContext } from "@paperclipai/plugin-sdk";
  3→import { fetchMarkets, filterByVolume } from "./scanner.js";
  4→import { buildAnalysisPrompt, parseAnalysisResponse } from "./analyzer.js";
  5→import { createSupabaseClient, upsertMarkets, updateNotifiedAt } from "./supabase.js";
  6→import type { PolymarketConfig, AnalyzedMarket, MarketEventPayload } from "./types.js";
  7→
  8→const PLUGIN_NAME = "polymarket-scanner";
  9→
 10→const plugin = definePlugin({
 11→  async setup(ctx) {
 12→    ctx.logger.info(`${PLUGIN_NAME} plugin setup complete`);
 13→
 14→    ctx.jobs.register("scan-polymarket", async (_job: PluginJobContext) => {
 15→      const scanRunning = await ctx.state.get({
 16→        scopeKind: "instance",
 17→        stateKey: "scanRunning",
 18→      });
 19→      if (scanRunning) {
 20→        ctx.logger.info("Scan already running, skipping this cycle");
 21→        return;
 22→      }
 23→
 24→      try {
 25→        await ctx.state.set(
 26→          { scopeKind: "instance", stateKey: "scanRunning" },
 27→          true,
 28→        );
 29→
 30→        const config = (await ctx.config.get()) as unknown as PolymarketConfig;
 31→        if (!config?.keywords?.length) {
 32→          ctx.logger.warn("No keywords configured, skipping scan");
 33→          return;
 34→        }
 35→        if (!config.supabaseUrl || !config.supabaseServiceKey) {
 36→          ctx.logger.warn("Supabase not configured, skipping scan");
 37→          return;
 38→        }
 39→        if (!config.agentSlug) {
 40→          ctx.logger.warn("Agent slug not configured, skipping scan");
 41→          return;
 42→        }
 43→        if (!config.companyId) {
 44→          ctx.logger.warn("Company ID not configured, skipping scan");
 45→          return;
 46→        }
 47→
 48→        const supabase = createSupabaseClient(
 49→          config.supabaseUrl,
 50→          config.supabaseServiceKey,
 51→        );
 52→
 53→        // 1. Fetch markets from Gamma API
 54→        const rawMarkets = await fetchMarkets(
 55→          ctx.http.fetch.bind(ctx.http),
 56→          config.keywords,
 57→        );
 58→        ctx.logger.info(`Fetched ${rawMarkets.length} markets from Gamma API`);
 59→
 60→        // 2. Filter by volume
 61→        const minVolume = config.minVolume ?? 0;
 62→        const filteredMarkets = filterByVolume(rawMarkets, minVolume);
 63→        ctx.logger.info(
 64→          `${filteredMarkets.length} markets pass volume threshold (${minVolume})`,
 65→        );
 66→
 67→        if (filteredMarkets.length === 0) {
 68→          await ctx.state.set(
 69→            { scopeKind: "instance", stateKey: "lastScanAt" },
 70→            new Date().toISOString(),
 71→          );
 72→          return;
 73→        }
 74→
 75→        // 3. AI analyze via agent sessions
 76→        const prompt = buildAnalysisPrompt(filteredMarkets, config.keywords);
 77→
 78→        // Find agent by slug
 79→        const agents = await ctx.agents.list({
 80→          companyId: config.companyId,
 81→        });
 82→        const agent = agents.find((a) => a.urlKey === config.agentSlug);
 83→        if (!agent) {
 84→          ctx.logger.error(
 85→            `Agent with slug "${config.agentSlug}" not found`,
 86→          );
 87→          return;
 88→        }
 89→
 90→        const session = await ctx.agents.sessions.create(
 91→          agent.id,
 92→          config.companyId,
 93→          { reason: "Polymarket market analysis" },
 94→        );
 95→
 96→        let aiResponseText = "";
 97→        await ctx.agents.sessions.sendMessage(
 98→          session.sessionId,
 99→          config.companyId,
100→          {
101→            prompt,
102→            reason: "Analyze markets for relevance",
103→            onEvent: (event) => {
104→              if (event.eventType === "chunk" && event.message) {
105→                aiResponseText += event.message;
106→              }
107→            },
108→          },
109→        );
110→
111→        const analysisResults = parseAnalysisResponse(aiResponseText);
112→        ctx.logger.info(
113→          `AI analysis returned ${analysisResults.length} results`,
114→        );
115→
116→        // 4. Build analyzed markets
117→        const analysisMap = new Map(
118→          analysisResults.map((r) => [r.market_id, r]),
119→        );
120→
121→        const analyzedMarkets: AnalyzedMarket[] = filteredMarkets.map((m) => {
122→          const analysis = analysisMap.get(m.market_id);
123→          return {
124→            ...m,
125→            matched_keywords: config.keywords.filter(
126→              (kw) =>
127→                m.question.toLowerCase().includes(kw.toLowerCase()) ||
128→                (m.description ?? "").toLowerCase().includes(kw.toLowerCase()),
129→            ),
130→            ai_relevance_score: analysis?.relevance_score ?? null,
131→            ai_analysis: analysis?.analysis ?? null,
132→          };
133→        });
134→
135→        // 5. Upsert ALL markets to Supabase
136→        const upsertResult = await upsertMarkets(supabase, analyzedMarkets);
137→        if (upsertResult.error) {
138→          ctx.logger.error(`Supabase upsert failed: ${upsertResult.error}`);
139→        }
140→
141→        // 6. Query Supabase for already-notified markets
142→        const { data: notifiedRows } = await supabase
143→          .from("polymarket_markets")
144→          .select("market_id")
145→          .not("notified_at", "is", null)
146→          .in(
147→            "market_id",
148→            analyzedMarkets.map((m) => m.market_id),
149→          );
150→        const alreadyNotified = new Set(
151→          (notifiedRows ?? []).map(
152→            (r: { market_id: string }) => r.market_id,
153→          ),
154→        );
155→
156→        // 7. Emit event for new markets (skip AI score filter for now)
157→        // TODO: uncomment AI score filter when ready:
158→        // const minScore = config.minAiRelevanceScore ?? 0.5;
159→        // const newRelevantMarkets = analyzedMarkets.filter(
160→        //   (m) => (m.ai_relevance_score ?? 0) >= minScore && !alreadyNotified.has(m.market_id),
161→        // );
162→        const newRelevantMarkets = analyzedMarkets.filter(
163→          (m) => !alreadyNotified.has(m.market_id),
164→        );
165→
166→        if (newRelevantMarkets.length > 0) {
167→          const payload: MarketEventPayload = {
168→            markets: newRelevantMarkets.map((m) => ({
169→              market_id: m.market_id,
170→              question: m.question,
171→              outcome_prices: m.outcome_prices,
172→              ai_relevance_score: m.ai_relevance_score ?? 0,
173→              ai_analysis: m.ai_analysis ?? "",
174→              url: m.url ?? "",
175→            })),
176→          };
177→          await ctx.events.emit(
178→            "new_markets",
179→            config.companyId,
180→            payload,
181→          );
182→          ctx.logger.info(
183→            `Emitted new_markets event for ${newRelevantMarkets.length} markets`,
184→          );
185→
186→          // 8. Update notified_at for emitted markets
187→          await updateNotifiedAt(
188→            supabase,
189→            newRelevantMarkets.map((m) => m.market_id),
190→          );
191→        }
192→
193→        await ctx.state.set(
194→          { scopeKind: "instance", stateKey: "lastScanAt" },
195→          new Date().toISOString(),
196→        );
197→
198→        // 9. Log activity
199→        await ctx.activity.log({
200→          companyId: config.companyId,
201→          message: `Scanned Polymarket: ${analyzedMarkets.length} markets analyzed, ${newRelevantMarkets.length} new relevant markets`,
202→          metadata: {
203→            plugin: PLUGIN_NAME,
204→            totalMarkets: rawMarkets.length,
205→            filtered: filteredMarkets.length,
206→            analyzed: analyzedMarkets.length,
207→            newRelevant: newRelevantMarkets.length,
208→          },
209→        });
210→      } finally {
211→        await ctx.state.set(
212→          { scopeKind: "instance", stateKey: "scanRunning" },
213→          false,
214→        );
215→      }
216→    });
217→
218→    // Action: test-pipeline — emit a fake event to test full flow
219→    ctx.actions.register("test-pipeline", async (_params: Record<string, unknown>) => {
220→      const config = (await ctx.config.get()) as unknown as PolymarketConfig;
221→      if (!config?.companyId) throw new Error("companyId not configured");
222→
223→      const fakeMarkets: MarketEventPayload = {
