          );

          // 5. Emit scan-complete event (always)
          const completePayload: ScanCompletePayload = {
            scannedAt: scanResult.scannedAt,
            coinCount: coins.length,
            coins,
          };
          await ctx.events.emit(
            "coingecko-scan-complete",
            config.companyId,
