457→import { definePlugin, runWorker } from "@paperclipai/plugin-sdk";
458→import type { PluginJobContext } from "@paperclipai/plugin-sdk";
459→import {
460→  fetchTopCoins,
461→  fetchTrendingCoins,
462→  fetchWatchlistCoins,
463→} from "./coingecko.js";
464→import type {
465→  CoingeckoConfig,
466→  CoinData,
467→  ScanResult,
468→  ScanCompletePayload,
469→  PriceAlertPayload,
470→} from "./types.js";
471→
472→const PLUGIN_NAME = "coingecko-scanner";
473→
474→const plugin = definePlugin({
475→  async setup(ctx) {
476→    ctx.logger.info(`${PLUGIN_NAME} plugin setup complete`);
477→
478→    ctx.jobs.register(
479→      "scan-coingecko",
480→      async (_job: PluginJobContext) => {
481→        // Guard: prevent concurrent scans
482→        const scanRunning = await ctx.state.get({
483→          scopeKind: "instance",
484→          stateKey: "scanRunning",
485→        });
486→        if (scanRunning) {
487→          ctx.logger.info("Scan already running, skipping this cycle");
488→          return;
489→        }
490→
491→        try {
492→          await ctx.state.set(
493→            { scopeKind: "instance", stateKey: "scanRunning" },
494→            true,
495→          );
496→
497→          const config =
498→            (await ctx.config.get()) as unknown as CoingeckoConfig;
499→          const hasCompanyId = !!config?.companyId;
500→          if (!hasCompanyId) {
501→            ctx.logger.warn(
502→              "companyId not configured — will scan and save state but skip events/issues",
503→            );
504→          }
505→
506→          const scanMode = config?.scanMode ?? "top";
507→          const currency = config.currency ?? "usd";
508→          const topLimit = config.topCoinsLimit ?? 20;
509→          const watchlistIds = (config.watchlistCoinIds ?? "bitcoin,ethereum,solana")
510→            .split(",")
511→            .map((s) => s.trim())
512→            .filter(Boolean);
513→
514→          // 1. Fetch coins based on scanMode
515→          let coins: CoinData[] = [];
516→          try {
517→            if (scanMode === "top" || scanMode === "all") {
518→              const topCoins = await fetchTopCoins(
519→                ctx.http.fetch.bind(ctx.http),
520→                currency,
521→                topLimit,
522→              );
523→              coins.push(...topCoins);
524→            }
525→            if (scanMode === "trending" || scanMode === "all") {
526→              const trendingCoins = await fetchTrendingCoins(
527→                ctx.http.fetch.bind(ctx.http),
528→              );
529→              coins.push(...trendingCoins);
530→            }
531→            if (scanMode === "watchlist" || scanMode === "all") {
532→              const watchlistCoins = await fetchWatchlistCoins(
533→                ctx.http.fetch.bind(ctx.http),
534→                watchlistIds,
535→                currency,
536→              );
537→              coins.push(...watchlistCoins);
538→            }
539→          } catch (err: unknown) {
540→            const message =
541→              err instanceof Error ? err.message : String(err);
542→            if (message.includes("429")) {
543→              ctx.logger.warn(
544→                `CoinGecko rate limited, skipping this cycle`,
545→              );
546→              return;
547→            }
548→            throw err;
549→          }
550→
551→          // Deduplicate by coin id (keep first occurrence)
552→          const seen = new Set<string>();
553→          coins = coins.filter((c) => {
554→            if (seen.has(c.id)) return false;
555→            seen.add(c.id);
556→            return true;
557→          });
558→
559→          ctx.logger.info(
560→            `Fetched ${coins.length} unique coins (mode: ${scanMode})`,
561→          );
562→
563→          // 2. Load previous scan for comparison
564→          const prevScan = (await ctx.state.get({
565→            scopeKind: "instance",
566→            stateKey: "last-scan",
567→          })) as ScanResult | null;
568→
569→          const prevMap = new Map<string, CoinData>();
570→          if (prevScan?.coins) {
571→            for (const c of prevScan.coins) {
572→              prevMap.set(c.id, c);
573→            }
574→          }
575→
576→          // 3. Compare and detect alerts
577→          const priceThreshold = config?.priceChangeThreshold ?? 10;
578→          const volumeThreshold = config?.volumeChangeThreshold ?? 50;
579→          let alertsTriggered = 0;
580→
581→          // 4. Save state FIRST (crash-safe: even if alerts fail, data is persisted)
582→          const scanResult: ScanResult = {
583→            scannedAt: new Date().toISOString(),
584→            scanMode,
585→            coins,
586→            alertsTriggered: 0, // updated below
587→          };
588→
589→          // 5. Process alerts (only if companyId set and not first scan)
590→          if (hasCompanyId && prevScan !== null) {
591→            for (const coin of coins) {
592→              const prev = prevMap.get(coin.id);
593→              const priceChange = Math.abs(coin.priceChange24hPercent);
594→
595→              let volumeChange: number | null = null;
596→              if (prev && prev.volume24h > 0) {
597→                volumeChange =
598→                  ((coin.volume24h - prev.volume24h) / prev.volume24h) *
599→                  100;
600→              }
601→
602→              const priceAlert = priceChange >= priceThreshold;
603→              const volumeAlert =
604→                volumeChange !== null &&
605→                Math.abs(volumeChange) >= volumeThreshold;
606→
607→              if (priceAlert || volumeAlert) {
608→                alertsTriggered++;
609→                const reasons: string[] = [];
610→                if (priceAlert) {
611→                  reasons.push(
612→                    `price ${coin.priceChange24hPercent > 0 ? "+" : ""}${coin.priceChange24hPercent.toFixed(1)}% (24h)`,
613→                  );
614→                }
615→                if (volumeAlert) {
616→                  reasons.push(
617→                    `volume ${volumeChange! > 0 ? "+" : ""}${volumeChange!.toFixed(1)}%`,
618→                  );
619→                }
620→                const reason = reasons.join(", ");
621→
622→                // Emit alert event
623→                const alertPayload: PriceAlertPayload = {
624→                  coin,
625→                  priceChangePercent: coin.priceChange24hPercent,
626→                  volumeChangePercent: volumeChange,
627→                  reason,
628→                };
629→                await ctx.events.emit(
630→                  "coingecko-price-alert",
631→                  config.companyId,
632→                  alertPayload,
633→                );
634→
635→                // Create issue
636→                const priority =
637→                  priceChange >= 20 ? "high" : "medium";
638→                const sign =
639→                  coin.priceChange24hPercent >= 0 ? "+" : "";
640→                await ctx.issues.create({
641→                  companyId: config.companyId,
642→                  title: `🔔 ${coin.symbol.toUpperCase()} ${sign}${coin.priceChange24hPercent.toFixed(1)}% trong 24h`,
643→                  description: `**${coin.name}** (${coin.symbol.toUpperCase()})\n\n- Giá: $${coin.currentPrice.toLocaleString()}\n- Thay đổi 24h: ${sign}${coin.priceChange24hPercent.toFixed(1)}%\n- Volume 24h: $${coin.volume24h.toLocaleString()}\n${volumeChange !== null ? `- Volume change: ${volumeChange > 0 ? "+" : ""}${volumeChange.toFixed(1)}%\n` : ""}\n**Reason:** ${reason}`,
644→                  priority,
645→                });
646→
647→                ctx.logger.info(
648→                  `Alert: ${coin.symbol} — ${reason}`,
649→                );
650→              }
651→            }
652→          }
653→
654→          // 6. Save scan result with final alert count
655→          scanResult.alertsTriggered = alertsTriggered;
656→          await ctx.state.set(
657→            { scopeKind: "instance", stateKey: "last-scan" },
658→            scanResult,
659→          );
660→
661→          // 7. Emit scan-complete event (only if companyId set)
662→          if (hasCompanyId) {
663→            const completePayload: ScanCompletePayload = {
664→              scannedAt: scanResult.scannedAt,
665→              coinCount: coins.length,
666→              coins,
667→            };
668→            await ctx.events.emit(
669→              "coingecko-scan-complete",
670→              config.companyId,
671→              completePayload,
672→            );
673→
674→            // 8. Activity log
675→            await ctx.activity.log({
676→              companyId: config.companyId,
677→              message: `Scanned CoinGecko: ${coins.length} coins, ${alertsTriggered} alerts triggered`,
678→              metadata: {
679→                plugin: PLUGIN_NAME,
680→                scanMode,
681→                totalCoins: coins.length,
682→                alertsTriggered,
683→              },
684→            });
685→          }
686→        } finally {
687→          await ctx.state.set(
688→            { scopeKind: "instance", stateKey: "scanRunning" },
689→            false,
690→          );
691→        }
692→      },
693→    );
694→
695→    // Data provider: scanner status for settings page
696→    ctx.data.register(
697→      "scanner-status",
698→      async (_params: Record<string, unknown>) => {
699→        const lastScan = (await ctx.state.get({
700→          scopeKind: "instance",
701→          stateKey: "last-scan",
702→        })) as ScanResult | null;
703→        const scanRunning = await ctx.state.get({
704→          scopeKind: "instance",
705→          stateKey: "scanRunning",
706→        });
707→        return {
708→          lastScanAt: lastScan?.scannedAt ?? null,
709→          scanRunning: !!scanRunning,
710→          coinCount: lastScan?.coins.length ?? 0,
711→          alertsTriggered: lastScan?.alertsTriggered ?? 0,
712→        };
713→      },
714→    );
715→  },
716→
717→  async onHealth() {
718→    return { status: "ok", message: "CoinGecko Scanner plugin ready" };
719→  },
720→
721→  async onValidateConfig(config: Record<string, unknown>) {
722→    const errors: string[] = [];
723→    if (!config.companyId) errors.push("companyId is required");
724→    return { ok: errors.length === 0, errors };
725→  },
726→});
727→
728→export default plugin;
729→runWorker(plugin, import.meta.url);
730→```
