244→import type {
245→  CoinData,
246→  CoinGeckoMarketItem,
247→  CoinGeckoTrendingResponse,
248→  CoinGeckoSimplePriceResponse,
249→} from "./types.js";
250→
251→const BASE_URL = "https://api.coingecko.com/api/v3";
252→
253→type FetchFn = (url: string, init?: RequestInit) => Promise<Response>;
254→
255→/**
256→ * Fetch top coins by market cap.
257→ */
258→export async function fetchTopCoins(
259→  fetchFn: FetchFn,
260→  currency: string,
261→  limit: number,
262→): Promise<CoinData[]> {
263→  const url = `${BASE_URL}/coins/markets?vs_currency=${currency}&order=market_cap_desc&per_page=${limit}&page=1&sparkline=false&price_change_percentage=24h`;
264→  const resp = await fetchFn(url);
265→  if (!resp.ok) {
266→    throw new Error(`CoinGecko /coins/markets failed: ${resp.status}`);
267→  }
268→  const items: CoinGeckoMarketItem[] = await resp.json();
269→  return items.map((item) => ({
270→    id: item.id,
271→    symbol: item.symbol,
272→    name: item.name,
273→    currentPrice: item.current_price ?? 0,
274→    priceChange24hPercent: item.price_change_percentage_24h ?? 0,
275→    volume24h: item.total_volume ?? 0,
276→    marketCap: item.market_cap ?? 0,
277→    source: "top" as const,
278→  }));
279→}
280→
281→/**
282→ * Fetch trending coins.
283→ */
284→export async function fetchTrendingCoins(
285→  fetchFn: FetchFn,
286→): Promise<CoinData[]> {
287→  const url = `${BASE_URL}/search/trending`;
288→  const resp = await fetchFn(url);
289→  if (!resp.ok) {
290→    throw new Error(`CoinGecko /search/trending failed: ${resp.status}`);
291→  }
292→  const data: CoinGeckoTrendingResponse = await resp.json();
293→  return data.coins.map((entry) => ({
294→    id: entry.item.id,
295→    symbol: entry.item.symbol,
296→    name: entry.item.name,
297→    currentPrice: entry.item.data?.price ?? 0,
298→    priceChange24hPercent:
299→      entry.item.data?.price_change_percentage_24h?.usd ?? 0,
300→    volume24h: parseFloat(entry.item.data?.total_volume ?? "0"),
301→    marketCap: parseFloat(entry.item.data?.market_cap ?? "0"),
302→    source: "trending" as const,
303→  }));
304→}
305→
306→/**
307→ * Fetch specific coins by IDs (watchlist).
308→ */
309→export async function fetchWatchlistCoins(
310→  fetchFn: FetchFn,
311→  coinIds: string[],
312→  currency: string,
313→): Promise<CoinData[]> {
314→  if (coinIds.length === 0) return [];
315→  const ids = coinIds.join(",");
316→  const url = `${BASE_URL}/simple/price?ids=${ids}&vs_currencies=${currency}&include_24hr_change=true&include_24hr_vol=true`;
317→  const resp = await fetchFn(url);
318→  if (!resp.ok) {
319→    throw new Error(`CoinGecko /simple/price failed: ${resp.status}`);
320→  }
321→  const data: CoinGeckoSimplePriceResponse = await resp.json();
322→  return Object.entries(data).map(([id, values]) => ({
323→    id,
324→    symbol: id,
325→    name: id,
326→    currentPrice: values[currency] ?? 0,
327→    priceChange24hPercent: values[`${currency}_24h_change`] ?? values.usd_24h_change ?? 0,
328→    volume24h: values[`${currency}_24h_vol`] ?? values.usd_24h_vol ?? 0,
329→    marketCap: 0,
330→    source: "watchlist" as const,
331→  }));
332→}
333→```
